"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[945],{1945:(e,l,r)=>{r.d(l,{w:()=>i});let a="https://github.com/Faithlife/SBLGNT/blob/master/data/sblgnt/text/Acts.txt";function t(e,l){return"https://bible.bskorea.or.kr/bible/NKRV/ACT.".concat(e,".").concat(l)}function s(e,l){return"https://bible.bskorea.or.kr/bible/NKT/ACT.".concat(e,".").concat(l)}function n(e,l){return"https://classic.net.bible.org/verse.php?book=Act&chapter=".concat(e,"&verse=").concat(l)}let i=[{id:"acts-2-1-supplied-they",chapter:2,reference:"행 2:1",category:"지시 대상",title:"원문에 따로 쓰이지 않은 ‘그들’은 누구인가",revisedPhrase:"“그들이 다같이 한 곳에 모였더니”",newKoreanPhrase:"“그들 모두가 같은 자리에 함께 있었다”",greek:"ἦσαν πάντες ὁμοῦ ἐπὶ τὸ αὐτό",possibleReading:"모두가 함께 있었다. 누구를 포함하는지는 앞뒤 장면에서 판단해야 한다",explanation:"헬라어에는 독립된 대명사 ‘그들’이 없다. 3인칭 복수 동사 ἦσαν과 ‘모두’를 뜻하는 πάντες가 있을 뿐이다. 두 한국어 역본은 문장을 자연스럽게 만들려고 ‘그들’을 보탰다. 따라서 1:26의 ‘열한 사도’가 가장 가까운 복수 명사라는 이유만으로 오순절의 무리를 열두 사도로 확정하면, 번역이 보탠 대명사를 원문의 논거로 삼는 셈이 된다.",sources:[{label:"개역개정 공식 본문",url:t(2,1)},{label:"새한글성경 공식 본문",url:s(2,1)},{label:"SBLGNT 원문",url:a},{label:"대명사 번역 연구",url:"https://translation.bible/wp-content/uploads/2024/06/moulton-1970-pronouns-in-the-new-testament.pdf"}]},{id:"acts-3-15-archegos",chapter:3,reference:"행 3:15",category:"낱말 의미",title:"‘생명의 주’인가, ‘생명의 창시자’인가",revisedPhrase:"“생명의 주”",newKoreanPhrase:"“생명의 창시자”",greek:"τὸν ἀρχηγὸν τῆς ζωῆς",possibleReading:"생명의 창시자 \xb7 생명의 선도자",explanation:"ἀρχηγός는 κύριος(주)와 다른 말이다. 어떤 일을 시작해 앞에서 이끄는 사람을 가리키므로 ‘창시자’, ‘선구자’, ‘지도자’의 뜻이 함께 있다. 베드로의 말은 사람들이 생명의 근원을 죽였지만 하나님이 그를 살리셨다는 역설을 만든다.",sources:[{label:"개역개정 공식 본문",url:t(3,15)},{label:"새한글성경 공식 본문",url:s(3,15)},{label:"SBLGNT 원문",url:a},{label:"NET 번역 주석",url:n(3,15)}]},{id:"acts-7-25-his-hand",chapter:7,reference:"행 7:25",category:"지시 대상",title:"‘자기의 손’은 하나님의 손인가, 모세의 손인가",revisedPhrase:"“하나님께서 자기의 손을 통하여 구원해 주시는 것”",newKoreanPhrase:"“하나님이 자기 손을 빌려 구원해 주시는 것”",greek:"ὁ θεὸς διὰ χειρὸς αὐτοῦ δίδωσιν σωτηρίαν αὐτοῖς",possibleReading:"하나님이 모세를 통하여 이스라엘 백성을 구원해 주신다",literalReading:"하나님이 그의 손을 통하여 그들에게 구원을 주신다",explanation:"αὐτοῦ는 3인칭 단수 소유 표현 ‘그의’다. 문맥에서는 모세를 가리키며, 원문 구절에 모세라는 이름이 다시 나오지는 않는다. 구원의 주체는 하나님이고 모세는 그 수단이다. 개역개정은 ‘하나님께서’ 바로 뒤에 ‘자기의 손’을 두어 하나님의 손으로 읽기 쉽다. 새한글성경도 모세를 먼저 이름 붙였지만 ‘자기 손’은 그대로 둔다.",sources:[{label:"개역개정 공식 본문",url:t(7,25)},{label:"새한글성경 공식 본문",url:s(7,25)},{label:"SBLGNT 원문",url:a},{label:"번역자 주석",url:"https://tips.translation.bible/tip_verse/acts-725/"}]},{id:"acts-8-26-south-noon",chapter:8,reference:"행 8:26",category:"문법\xb7문장",title:"‘남쪽으로’와 ‘한낮에’가 모두 가능한 문장",revisedPhrase:"“남쪽으로 향하여 … 그 길은 광야라”",newKoreanPhrase:"“남쪽으로 … 그 길은 외진 길입니다”",greek:"κατὰ μεσημβρίαν … αὕτη ἐστὶν ἔρημος",possibleReading:"남쪽으로 가라 / 한낮에 가라 \xb7 이 길은 광야 길이다",explanation:"μεσημβρία는 방향인 ‘남쪽’과 시간인 ‘정오’를 모두 나타낼 수 있다. 개역개정과 새한글성경은 방향을 택했다. 빌립이 예루살렘에서 가사로 내려가는 길을 찾는 장면에는 잘 맞지만, 문법만으로 ‘한낮에’라는 읽기를 지울 수는 없다.",sources:[{label:"개역개정 공식 본문",url:t(8,26)},{label:"새한글성경 공식 본문",url:s(8,26)},{label:"SBLGNT 원문",url:a},{label:"NET 번역 주석",url:n(8,26)}]},{id:"acts-8-26-this-road-or-gaza",chapter:8,reference:"행 8:26",category:"지시 대상",title:"‘이것’은 길인가, 가사 성읍인가",revisedPhrase:"“그 길은 광야라”",newKoreanPhrase:"“그 길은 외진 길입니다”",greek:"αὕτη ἐστὶν ἔρημος",possibleReading:"이 길은 외딴 길이다 / 이 가사는 버려진 곳이다",explanation:"여성 지시대명사 αὕτη는 앞 문장의 여성명사인 ‘길’(ὁδός)과 ‘가사’(Γάζα)를 모두 받을 수 있다. 두 한국어 역본은 ‘길’을 가리킨다고 풀었다. 오늘날 널리 쓰이는 읽기이지만, 오래된 주석 전통에는 옛 가사 성읍을 가리킨다는 해석도 있다. 이 대목은 번역이 모호성을 없앤 선택이지, 개역개정만의 확정 오류는 아니다.",sources:[{label:"개역개정 공식 본문",url:t(8,26)},{label:"새한글성경 공식 본문",url:s(8,26)},{label:"SBLGNT 원문",url:a},{label:"대명사 번역 연구",url:"https://translation.bible/wp-content/uploads/2024/06/moulton-1970-pronouns-in-the-new-testament.pdf"}]},{id:"acts-10-34-partiality",chapter:10,reference:"행 10:34",category:"낱말 의미",title:"‘외모’는 생김새가 아니라 편파적인 대우를 뜻한다",revisedPhrase:"“사람의 외모를 보지 아니하시고”",newKoreanPhrase:"“겉모습을 보고 차별하시는 분이 아닙니다”",greek:"οὐκ ἔστιν προσωπολήμπτης ὁ θεός",possibleReading:"하나님은 사람을 편파적으로 대하지 않으신다",explanation:"προσωπολήμπτης는 문자적으로 ‘얼굴을 받아 주는 사람’이지만 실제 뜻은 신분이나 집단에 따라 편드는 사람이다. 고넬료 사건에서 문제 되는 것은 외형이 아니라 유대인과 이방인을 가르던 경계다.",sources:[{label:"개역개정 공식 본문",url:t(10,34)},{label:"새한글성경 공식 본문",url:s(10,34)},{label:"SBLGNT 원문",url:a},{label:"NET 번역 주석",url:n(10,34)}]},{id:"acts-11-20-hellenists",chapter:11,reference:"행 11:20",category:"본문 전승",title:"안디옥에서 복음을 들은 사람은 ‘헬라인’인가",revisedPhrase:"“헬라인에게도 말하여”",newKoreanPhrase:"“그리스말을 쓰는 사람들한테도”",greek:"πρὸς τοὺς Ἑλληνιστάς / πρὸς τοὺς Ἕλληνας",possibleReading:"헬라파 유대인들에게 / 헬라인들에게",explanation:"그리스어 사본에는 ‘헬라파 유대인’과 ‘헬라인’이라는 두 읽기가 전해진다. SBLGNT는 Ἑλληνιστάς를 본문에 두지만, 개역개정은 Ἕλληνας에 해당하는 ‘헬라인’을 택했다. 어느 읽기를 택하느냐에 따라 안디옥의 이방인 선교가 시작되는 장면을 설명하는 방식이 달라진다.",sources:[{label:"개역개정 공식 본문\xb7각주",url:t(11,20)},{label:"새한글성경 공식 본문",url:s(11,20)},{label:"SBLGNT 원문",url:a},{label:"공개 본문비평 주석",url:"https://www.bibliaplus.org/en/commentaries/428/a-textual-commentary-on-the-greek-new-testament-by-bruce-m-metzger/acts/11/20"}]},{id:"acts-16-16-python",chapter:16,reference:"행 16:16",category:"문화 배경",title:"‘점치는 귀신’ 뒤에 있는 피톤 신탁의 세계",revisedPhrase:"“점치는 귀신 들린 여종”",newKoreanPhrase:"“점치는 영에 붙들린 어떤 여자종”",greek:"ἔχουσαν πνεῦμα πύθωνα",possibleReading:"피톤의 영을 지닌 여종",explanation:"πύθων은 본래 델포이 신탁과 아폴론 전승에 연결된 피톤을 가리킨다. 개역개정은 기능을 분명히 전달하지만, 빌립보 사람들이 이 여종을 그리스\xb7로마의 신탁 문화 안에서 이해했다는 배경은 보이지 않는다.",sources:[{label:"개역개정 공식 본문",url:t(16,16)},{label:"새한글성경 공식 본문",url:s(16,16)},{label:"SBLGNT 원문",url:a},{label:"NET 번역 주석",url:n(16,16)}]},{id:"acts-17-18-seed-picker",chapter:17,reference:"행 17:18",category:"문화 배경",title:"‘말쟁이’보다 모욕적인 ‘씨앗 줍는 자’",revisedPhrase:"“이 말쟁이가”",newKoreanPhrase:"“이 떠버리가”",greek:"ὁ σπερμολόγος οὗτος",possibleReading:"이 잡동사니 지식이나 주워 모으는 자가",explanation:"σπερμολόγος는 씨앗을 쪼아 먹는 새나 시장의 부스러기를 줍는 사람에서 나온 비하 표현이다. 여기서는 남의 생각을 조금씩 주워 와 아는 체하는 사람이라는 조롱에 가깝다. ‘말이 많은 사람’이라는 뜻만으로는 아덴 철학자들의 경멸이 약해진다.",sources:[{label:"개역개정 공식 본문",url:t(17,18)},{label:"새한글성경 공식 본문",url:s(17,18)},{label:"SBLGNT 원문",url:a},{label:"NET 번역 주석",url:n(17,18)}]},{id:"acts-17-22-religious",chapter:17,reference:"행 17:22",category:"낱말 의미",title:"‘종교심이 많다’는 칭찬인가 비판인가",revisedPhrase:"“범사에 종교심이 많도다”",newKoreanPhrase:"“얼마나 신을 두려워하는지”",greek:"δεισιδαιμονεστέρους",possibleReading:"매우 종교적이다 / 다소 미신적이다",explanation:"이 비교급은 경건함을 인정하는 말과 미신적이라는 비판을 모두 허용한다. 바울은 청중의 관심을 얻는 말로 시작하지만, 이어지는 설교에서 그들의 무지를 곧바로 지적한다. 개역개정은 긍정적인 쪽을 선택했다.",sources:[{label:"개역개정 공식 본문",url:t(17,22)},{label:"새한글성경 공식 본문",url:s(17,22)},{label:"SBLGNT 원문",url:a},{label:"NET 번역 주석",url:n(17,22)}]},{id:"acts-19-2-believing",chapter:19,reference:"행 19:2",category:"문법\xb7문장",title:"‘믿을 때’인가, ‘믿은 뒤’인가",revisedPhrase:"“너희가 믿을 때에 성령을 받았느냐”",newKoreanPhrase:"“믿었을 때에 성령을 받았습니까?”",greek:"Εἰ πνεῦμα ἅγιον ἐλάβετε πιστεύσαντες;",possibleReading:"믿었을 때 성령을 받았느냐 / 믿은 뒤 성령을 받았느냐",explanation:"부정과거 분사 πιστεύσαντες는 문맥에 따라 주동사의 사건과 거의 동시에 일어난 믿음 또는 그보다 앞선 믿음을 나타낼 수 있다. 문법 하나만으로 성령을 받는 시점을 확정하기 어렵다. 이어지는 질문은 이 사람들이 무엇을 믿었는지를 먼저 확인하게 한다.",sources:[{label:"개역개정 공식 본문",url:t(19,2)},{label:"새한글성경 공식 본문",url:s(19,2)},{label:"SBLGNT 원문",url:a},{label:"NET 본문\xb7주석",url:n(19,2)}]},{id:"acts-20-28-own-blood",chapter:20,reference:"행 20:28",category:"문법\xb7문장",title:"‘자기 피’와 ‘자기 아들의 피’",revisedPhrase:"“하나님이 자기 피로 사신 교회”",newKoreanPhrase:"“자신의 피를 통해서 자신의 것으로 만드신 교회”",greek:"διὰ τοῦ αἵματος τοῦ ἰδίου",possibleReading:"자기 자신의 피로 / 자기에게 속한 이의 피, 곧 자기 아들의 피로",explanation:"τοῦ ἰδίου를 ‘자기 자신의’이라는 수식어로 읽으면 개역개정과 같다. ὁ ἴδιος가 ‘자기에게 속한 이’를 가리키는 명사적 표현이라고 보면 ‘자기 아들의 피’라는 번역도 가능하다. 여기에 ‘하나님의 교회/주의 교회’라는 사본 차이도 얽혀 있다.",sources:[{label:"개역개정 공식 본문\xb7각주",url:t(20,28)},{label:"새한글성경 공식 본문",url:s(20,28)},{label:"SBLGNT 원문",url:a},{label:"NET 번역\xb7본문비평 주석",url:n(20,28)}]},{id:"acts-21-19-his-ministry",chapter:21,reference:"행 21:19",category:"지시 대상",title:"‘자기의 사역’은 하나님의 사역인가, 바울의 사역인가",revisedPhrase:"“하나님이 자기의 사역으로 말미암아 … 하신 일”",newKoreanPhrase:"“자기의 섬김을 통하여 하나님이 … 행하신 일들”",greek:"ὧν ἐποίησεν ὁ θεὸς … διὰ τῆς διακονίας αὐτοῦ",possibleReading:"하나님이 바울의 사역을 통하여 이방인 가운데서 하신 일",literalReading:"하나님이 … 그의 사역을 통하여 행하신 일들",explanation:"αὐτοῦ는 3인칭 단수 소유 표현 ‘그의’다. 여기서 일을 행한 분은 하나님이고, 문맥상 ‘그’는 바울이다. ‘바울의 사역’은 지시 대상을 이름으로 풀어 쓴 번역이다. 개역개정의 ‘하나님이 자기의 사역으로’는 ‘자기’를 하나님에게 붙여 읽게 한다. 새한글성경은 ‘자기의 섬김’을 먼저 놓은 뒤 ‘하나님이’를 써서 사역의 주인과 행위 주체를 구별한다.",sources:[{label:"개역개정 공식 본문",url:t(21,19)},{label:"새한글성경 공식 본문",url:s(21,19)},{label:"SBLGNT 원문",url:a},{label:"NET 번역 주석",url:n(21,19)}]},{id:"acts-22-9-hearing",chapter:9,relatedChapters:[9,22],reference:"행 9:7; 22:9",category:"문법\xb7문장",title:"동행자들은 소리를 들었는가, 듣지 못했는가",revisedPhrase:"“소리는 듣지 못하더라”",newKoreanPhrase:"“말씀하시는 분의 목소리는 듣지 못했습니다”",greek:"τὴν δὲ φωνὴν οὐκ ἤκουσαν",possibleReading:"그 음성을 듣지 못했다 / 그 음성을 알아듣지 못했다",explanation:"행 9:7은 동행자들이 ‘소리’를 들었다고 하고, 행 22:9은 듣지 못했다고 말한다. ἀκούω는 소리를 듣는 것과 뜻을 알아듣는 것을 모두 나타낼 수 있다. ‘소리는 들었지만 말의 내용은 알아듣지 못했다’는 해석이 가능하지만, 격의 차이만으로 이를 기계적으로 증명할 수는 없다.",sources:[{label:"개역개정 행 22장",url:t(22,9)},{label:"개역개정 행 9장",url:t(9,7)},{label:"새한글성경 행 22장",url:s(22,9)},{label:"새한글성경 행 9장",url:s(9,7)},{label:"NET 번역 주석",url:n(22,9)}]},{id:"acts-24-14-sect",chapter:24,reference:"행 24:5, 14",category:"낱말 의미",title:"1세기의 ‘파’가 후대의 ‘이단’이 될 때",revisedPhrase:"“나사렛 이단” \xb7 “이단이라 하는 도”",newKoreanPhrase:"“나사렛 사람들 분파” \xb7 “분파라고 말하는 그 믿음의 길”",greek:"αἵρεσις",possibleReading:"나사렛파 \xb7 그들이 한 분파라고 부르는 그 길",explanation:"αἵρεσις는 이 문맥에서 바리새파나 사두개파처럼 특정 집단이나 분파를 가리킨다. 후대 교회의 ‘정통 교리를 부정하는 이단’이라는 기술적 의미를 바로 대입하면, 더둘로의 정치적 고발과 바울의 법정 변론을 오해하기 쉽다.",sources:[{label:"개역개정 공식 본문",url:t(24,14)},{label:"새한글성경 공식 본문",url:s(24,14)},{label:"SBLGNT 원문",url:a},{label:"NET 본문",url:n(24,14)}]},{id:"acts-26-28-en-oligo",chapter:26,reference:"행 26:28",category:"문법\xb7문장",title:"아그립바의 말은 질문인가, 빈정거림인가",revisedPhrase:"“적은 말로 나를 권하여 … 되게 하려 하는도다”",newKoreanPhrase:"“잠깐 사이에 나를 설득해서 … 만들려고 하는구나”",greek:"Ἐν ὀλίγῳ με πείθεις Χριστιανὸν ποιῆσαι",possibleReading:"그렇게 짧은 말이나 시간으로 나를 그리스도인으로 설득하려는가? / 적은 노력으로 나를 그리스도인으로 만들려는가?",explanation:"ἐν ὀλίγῳ는 ‘짧은 말이나 시간에’와 ‘적은 노력으로’를 모두 허용하며, 문장에는 물음표가 전해진 것이 아니다. 개역개정은 단정적인 말처럼 옮겼지만 질문, 회피, 반어가 섞인 응답일 수 있다. 아그립바가 거의 회심했다는 뜻으로 단정할 수 없다.",sources:[{label:"개역개정 공식 본문\xb7각주",url:t(26,28)},{label:"새한글성경 공식 본문",url:s(26,28)},{label:"SBLGNT 원문",url:a},{label:"NET 번역 주석",url:n(26,28)}]},{id:"acts-28-4-justice",chapter:28,reference:"행 28:4",category:"문화 배경",title:"‘공의’가 의인화된 디케로 들릴 수 있다",revisedPhrase:"“공의가 그를 살지 못하게 함이로다”",newKoreanPhrase:"“디케(정의의 여신)가 … 살게 내버려 두지 않았다”",greek:"ἡ δίκη ζῆν οὐκ εἴασεν",possibleReading:"정의의 여신 디케가 그를 살려 두지 않았다",explanation:"관사와 문맥을 고려하면 Δίκη는 죄인을 추적해 벌하는 정의의 여신을 의인화한 말로 읽을 수 있다. 개역개정은 ‘공의’라는 추상명사로 옮겨 의미는 전달하지만, 멜리데 주민들의 종교 세계는 보이지 않는다.",sources:[{label:"개역개정 공식 본문",url:t(28,4)},{label:"새한글성경 공식 본문",url:s(28,4)},{label:"SBLGNT 원문",url:a},{label:"NET 번역 주석",url:n(28,4)}]}]}}]);